import type {HandoffScope} from './cashier-handoff';
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
function obj(v:unknown):Record<string,unknown>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid deposit data.');return v as Record<string,unknown>}
function label(v:unknown,max:number){if(typeof v!=='string'||!v.trim()||v!==v.trim()||v.length>max||/[\x00-\x1f\x7f]/.test(v))throw Error('Invalid deposit details.');return v}
function amount(v:unknown){if(typeof v!=='string'||!/^[1-9][0-9]{0,11}$/.test(v))throw Error('Invalid deposit amount.');return v}
export function readBankDeposits(value:unknown,scope:HandoffScope,before:string|null=null){
 const v=obj(value);if(!Object.values(scope).every(uuid)||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.currency!=='USD'||!['property','own'].includes(String(v.scope))||v.live_view!==true||!Array.isArray(v.entries)||v.entries.length>50)throw Error('Deposit workspace changed.');
 let prior=before;const entries=v.entries.map(value=>{const d=obj(value);if(!uuid(d.id)||!uuid(d.actor_id)||d.tenant_id!==scope.tenant||d.property_id!==scope.property||(v.scope==='own'&&d.actor_id!==scope.actor)||(prior!==null&&d.id>=prior)||!['declared','voided'].includes(String(d.status))||d.bank_verified!==false||d.journal_posted!==false||typeof d.deposit_date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d.deposit_date)||!Array.isArray(d.allocations)||d.allocations.length<1||d.allocations.length>100)throw Error('Invalid deposit entry.');prior=d.id;
 const total=amount(d.amount_minor),seen=new Set<string>(),allocationCount=d.allocations.length;const allocations=d.allocations.map(value=>{const a=obj(value);const direct=a.session_id!==undefined;const source=direct?a.session_id:a.handoff_id;if(!uuid(source)||seen.has(source)||(direct&&(a.handoff_id!==undefined||allocationCount!==1))||(!direct&&a.session_id!==undefined))throw Error('Invalid deposit cash source.');seen.add(source);return {handoff:direct?null:source,session:direct?source:null,amount:amount(a.amount_minor)}});
 if(allocations.reduce((sum,a)=>sum+BigInt(a.amount),BigInt(0))!==BigInt(total)||d.handoff_id!==(allocations.length===1?allocations[0].handoff:null))throw Error('Deposit sources do not reconcile.');
 if(d.status==='voided'){if(!uuid(d.void_actor))throw Error('Invalid deposit void.');label(d.void_reason,500);label(d.voided_at,100)}else if(d.void_actor!=null||d.void_reason!=null||d.voided_at!=null)throw Error('Invalid active deposit.');
 if(d.bank_account_id!=null){if(!uuid(d.bank_account_id))throw Error('Invalid assigned bank account.');label(d.bank_account_label,80)}else if(d.bank_account_label!=null)throw Error('Bank account identity is missing.');
 return {accountId:(d.bank_account_id??null) as string|null,accountLabel:(d.bank_account_label??null) as string|null,status:d.status as 'declared'|'voided',voidReason:d.void_reason as string|null,id:d.id,actor:d.actor_id,total,bank:label(d.bank_label,80),reference:label(d.deposit_reference,120),date:d.deposit_date,reason:label(d.reason,500),createdAt:label(d.created_at,100),allocations};});
 if(v.next_before!==null&&(!uuid(v.next_before)||entries.length!==50||v.next_before!==entries[49].id))throw Error('Invalid deposit page cursor.');return {entries,next:v.next_before as string|null};
}

const date=(v:unknown):v is string=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
export function readDepositSources(value:unknown,scope:HandoffScope,before:string|null=null){const v=obj(value);if(v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.currency!=='USD'||!date(v.today)||typeof v.paused!=='boolean'||!Array.isArray(v.entries)||v.entries.length>50)throw Error('Deposit source workspace changed.');let prior=before;const entries=v.entries.map(value=>{const a=obj(value);if(!uuid(a.handoff_id)||(prior!==null&&a.handoff_id>=prior)||!date(a.earliest_deposit_date)||a.earliest_deposit_date>String(v.today))throw Error('Invalid deposit source.');prior=a.handoff_id;const available=amount(a.available_minor);if(BigInt(available)>BigInt(amount(a.received_minor)))throw Error('Invalid available cash.');return {id:a.handoff_id,available,earliest:a.earliest_deposit_date}});if(v.next_before!==null&&(!uuid(v.next_before)||entries.length!==50||entries[49].id!==v.next_before))throw Error('Invalid source page.');return {entries,next:v.next_before as string|null,today:v.today,paused:v.paused};}
export type DepositRequest={scope:HandoffScope;request:string;account?:string;bank:string;reference:string;date:string;reason:string;allocations:{handoff_id:string;amount_minor:string}[]};
function checkedRequest(value:unknown,scope:HandoffScope):DepositRequest{const v=obj(value),s=obj(v.scope);if(!Object.values(scope).every(uuid)||s.tenant!==scope.tenant||s.property!==scope.property||s.actor!==scope.actor||!uuid(v.request)||!date(v.date)||!Array.isArray(v.allocations)||v.allocations.length<1||v.allocations.length>100)throw Error('Invalid pending deposit.');const seen=new Set<string>();const allocations=v.allocations.map(value=>{const a=obj(value);if(!uuid(a.handoff_id)||seen.has(a.handoff_id))throw Error('Invalid deposit source.');seen.add(a.handoff_id);return {handoff_id:a.handoff_id,amount_minor:amount(a.amount_minor)}}).sort((a,b)=>a.handoff_id.localeCompare(b.handoff_id));if(allocations.reduce((sum,a)=>sum+BigInt(a.amount_minor),BigInt(0))>BigInt('999999999999'))throw Error('Deposit exceeds the supported amount.');const bank=label(v.bank,80),reference=label(v.reference,120),reason=label(v.reason,500);if(bank.length<2||reference.length<2||reason.length<4)throw Error('Complete the deposit details.');if(v.account!==undefined&&!uuid(v.account))throw Error('Invalid bank account.');return {scope:{...scope},request:v.request,...(v.account===undefined?{}:{account:v.account}),bank,reference,date:v.date,reason,allocations};}
export function prepareDepositRequest(value:DepositRequest){if(!uuid(value.account))throw Error('Choose a configured bank account.');return checkedRequest(value,value.scope)}
export function depositArgs(r:DepositRequest){return {p_tenant:r.scope.tenant,p_property:r.scope.property,p_request:r.request,p_allocations:r.allocations,p_bank_account:r.account,p_deposit_reference:r.reference,p_deposit_date:r.date,p_reason:r.reason,p_confirmed:true}}
export function readDepositReceipt(value:unknown,r:DepositRequest){const v=obj(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.actor_id!==r.scope.actor||v.request_id!==r.request||v.bank_label!==r.bank||(r.account!==undefined&&v.bank_account_id!==r.account)||v.deposit_reference!==r.reference||v.deposit_date!==r.date||v.reason!==r.reason||v.bank_verified!==false||v.journal_posted!==false||typeof v.replayed!=='boolean'||JSON.stringify(Array.isArray(v.allocations)?v.allocations.map(a=>{const x=obj(a);return [x.handoff_id,x.amount_minor]}):null)!==JSON.stringify(r.allocations.map(a=>[a.handoff_id,a.amount_minor]))||v.amount_minor!==r.allocations.reduce((sum,a)=>sum+BigInt(a.amount_minor),BigInt(0)).toString())throw Error('Deposit receipt does not match the pending request.');label(v.created_at,100);return v}
export function readDepositStatus(value:unknown,r:DepositRequest){const v=obj(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.actor_id!==r.scope.actor||v.request_id!==r.request||typeof v.found!=='boolean')throw Error('Deposit recovery scope changed.');if(!v.found){if(v.result!==null)throw Error('Invalid deposit recovery.');return null}return readDepositReceipt(v.result,r)}
type Store=Pick<Storage,'getItem'|'setItem'|'removeItem'>;function key(s:HandoffScope){if(!Object.values(s).every(uuid))throw Error('Invalid deposit scope.');return 'irp.deposit.pending.v1:'+ [s.tenant,s.property,s.actor].join(':')}
export function loadDeposit(store:Store,scope:HandoffScope){const raw=store.getItem(key(scope));return raw===null?null:checkedRequest(JSON.parse(raw),scope)}
export function saveDeposit(store:Store,r:DepositRequest){const encoded=JSON.stringify(checkedRequest(r,r.scope)),prior=loadDeposit(store,r.scope);if(prior&&JSON.stringify(prior)!==encoded)throw Error('Recover the pending deposit first.');store.setItem(key(r.scope),encoded);if(store.getItem(key(r.scope))!==encoded)throw Error('Unable to preserve deposit recovery.')}
export function clearDeposit(store:Store,r:DepositRequest){const prior=loadDeposit(store,r.scope);if(prior&&prior.request!==r.request)throw Error('A different deposit is pending.');store.removeItem(key(r.scope));if(store.getItem(key(r.scope))!==null)throw Error('Unable to clear deposit recovery.')}

export function readDepositCancellation(value:unknown,r:DepositRequest){const v=obj(value);if(v.schema_version!==1||v.tenant_id!==r.scope.tenant||v.property_id!==r.scope.property||v.actor_id!==r.scope.actor||v.request_id!==r.request||v.cancelled!==true||typeof v.replayed!=='boolean')throw Error('Deposit cancellation does not match the pending request.');label(v.created_at,100);return v}

export function readBankAccounts(value:unknown,scope:HandoffScope,before:string|null=null){const v=obj(value);if(v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.currency!=='USD'||v.bank_connected!==false||!Array.isArray(v.entries)||v.entries.length>50)throw Error('Bank account workspace changed.');let prior=before;const entries=v.entries.map(value=>{const a=obj(value);if(!uuid(a.account_id)||(prior!==null&&a.account_id>=prior))throw Error('Invalid bank account page.');prior=a.account_id;return {id:a.account_id,label:label(a.label,80),code:label(a.code,40)}});if(v.next_before!==null&&(!uuid(v.next_before)||entries.length!==50||entries[49].id!==v.next_before))throw Error('Invalid bank page cursor.');return {entries,next:v.next_before as string|null};}
